import clsx from 'clsx';
import React, {
  forwardRef,
  useEffect,
  useImperativeHandle,
  useRef,
} from 'react';
import type { RequireAtLeastOne } from 'type-fest';

import { CalendarHeader } from './calendar-header/CalendarHeader.js';
import {
  calendarBodyCSS,
  calendarCSS,
  calendarDisabledCSS,
} from './Calendar.sty.js';
import { CalendarContext } from './contexts/CalendarContext.js';
import { UseCalendarProps, _useCalendar } from './hooks/useCalendar.js';
import type { _CalendarViewType } from './types/shared-types.js';
import { _isCompleteSelection } from './utils/helpers.js';
import { SelectDayView } from './views/SelectDayView.js';
import { SelectMonthView } from './views/SelectMonthView.js';
import { SelectYearView } from './views/SelectYearView.js';
import { _VisuallyHidden as VisuallyHidden } from '../../../core/components/visually-hidden/VisuallyHidden.js';
import { SharedInputPropsContext } from '../../../core/contexts/SharedInputPropsContext.js';
import { _useControllableState } from '../../../core/hooks/useControllableState.js';
import { DataTestId } from '../../../core/types/data-props.js';
import type { FormControlProps } from '../../../core/types/form-control-props.js';
import { StylingProps } from '../../../core/types/styling-props.js';
import type { TimeframeV2 } from '../../../core/types/time.js';
import { _useFormFieldContext } from '../../forms-core/hooks/useFormFieldContext.js';
import { useFormFieldMessagesContext } from '../../forms-core/hooks/useFormFieldMessagesContext.js';
import { _useFormFieldValidation } from '../../forms-core/hooks/useFormFieldValidation.js';
import { FormFieldAction } from '../../forms-core/state/formfield-state-reducer.js';
import { _isTimeframeV2 } from '../../forms-core/time/types.js';
import type { FormControlRef, TimeRangePickerRef } from '../../shared-types.js';

//#region types
/** @internal */
export type _CalendarValueType<Type extends _CalendarType> =
  Type extends 'range'
    ? RequireAtLeastOne<TimeframeV2> | null
    : string | null | Date;

/** @internal */
export type _CalendarOnChangeType<Type extends _CalendarType> =
  Type extends 'range' ? TimeframeV2 | null : string | null;

/** @internal */
export interface _CalendarControlledProps<Type extends _CalendarType> {
  /** Controlled value used for the date in ISO string format. */
  value: _CalendarValueType<Type>;
  /** Callback triggered when the calendar value changes. */
  onChange: (date: _CalendarOnChangeType<Type>) => void;
  /** Initial value of the control which will be automatically updated with user input. */
  defaultValue?: never;
}

/** @internal */
export interface _CalendarUncontrolledProps<Type extends _CalendarType> {
  /** Initial value of the control which will be automatically updated with user input. */
  defaultValue?: _CalendarValueType<Type>;
  /** Callback triggered when the calendar value changes. */
  onChange?: (date: _CalendarOnChangeType<Type>) => void;
  /** Controlled value used for the date in ISO string format. */
  value?: never;
}

/**
 * @internal
 */
export type _CalendarType = 'single' | 'range' | undefined;

/** @internal */
export interface _CalendarBaseProps<Type extends _CalendarType> {
  /** The earliest selectable date. It will always consider the start of the day as time. */
  min?: string;
  /** The latest selectable date. It will always consider the end of the day as time. */
  max?: string;
  /** Determines the calendar type. Single allows the selection of one date and range allows a range selection with a from and to value.
   * @defaultValue 'single'
   */
  type?: Type | undefined;
  /** Callback triggered when the calendar value changes. */
  onChange?: (date: _CalendarOnChangeType<Type>) => void;
}

/** @internal */
export type _CalendarProps<Type extends _CalendarType> =
  _CalendarBaseProps<Type> &
    FormControlProps<
      _CalendarValueType<Type>,
      (date: _CalendarOnChangeType<Type>) => void
    > &
    StylingProps &
    DataTestId;
//#endregion

/** Render the correct view depending on the currentView state. */
function renderView(view: _CalendarViewType) {
  switch (view) {
    case 'month':
      return <SelectMonthView />;
    case 'year':
      return <SelectYearView />;
    default:
      return <SelectDayView />;
  }
}

/**
 * Calendar component
 * Renders the calendar header and body depending on the current view
 * @internal
 */
function _MappedCalendar<Type extends _CalendarType = 'single'>(
  props: _CalendarProps<Type>,
  forwardedRef: React.Ref<
    | FormControlRef<HTMLDivElement>
    | (Omit<FormControlRef<HTMLDivElement>, 'inputRef'> &
        Pick<TimeRangePickerRef<HTMLDivElement>, 'inputRef'>)
  >,
) {
  const {
    value,
    onChange,
    defaultValue,
    className: consumerClassName,
    style: consumerStyle,
    'data-testid': dataTestId,
    id: propId,
    disabled: propDisabled,
    required: propRequired,
    name,
    readOnly,
    type = 'single',
    ...remainingProps
  }: _CalendarProps<Type> = props;

  const [internalValue, setInternalValue] = _useControllableState({
    defaultValue:
      defaultValue instanceof Date
        ? (defaultValue.toISOString() as _CalendarOnChangeType<Type>)
        : defaultValue,
    value:
      value instanceof Date
        ? (value.toISOString() as _CalendarOnChangeType<Type>)
        : value,
    onChange,
  });

  // Imperative Handle Construction
  const calendarRef = useRef<HTMLDivElement>(null);
  const focusAfterViewChangeRef = useRef<HTMLButtonElement>(null);
  const ref = useRef<HTMLInputElement>(null);
  const refTo = useRef<HTMLInputElement>(null);

  useImperativeHandle(
    forwardedRef,
    ():
      | FormControlRef<HTMLDivElement>
      | (Omit<FormControlRef<HTMLDivElement>, 'inputRef'> &
          Pick<TimeRangePickerRef<HTMLDivElement>, 'inputRef'>) => {
      if (type === 'single') {
        return {
          element: calendarRef.current,
          inputRef: ref.current,
        };
      }

      return {
        element: calendarRef.current,
        inputRef: {
          from: ref?.current,
          to: refTo?.current,
        },
      };
    },
    [type],
  );

  // FormFieldContext Sync
  const {
    controlId,
    required: contextRequired,
    disabled: contextDisabled,
    dispatch: formFieldContextDispatch,
  } = _useFormFieldContext();
  const { state: messageState } = useFormFieldMessagesContext();

  useEffect(() => {
    formFieldContextDispatch?.({
      type: FormFieldAction.UPDATE,
      payload: {
        id: propId,
        disabled: propDisabled,
        required: propRequired,
      },
    });
  }, [formFieldContextDispatch, propDisabled, propId, propRequired]);

  const { ariaProps, eventListeners } = _useFormFieldValidation(ref.current);

  useEffect(() => {
    if (messageState.hasError) {
      // cleans up the required error
      eventListeners.onChange();
    }
    // eventListeners is excluded since it is changed every render
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [internalValue, messageState.hasError]);

  const { uniqueId, state, dispatch } = _useCalendar<Type>({
    calendarRef,
    focusAfterViewChangeRef,
    value: internalValue,
    onChange: setInternalValue,
    type,
    ...remainingProps,
  } as UseCalendarProps<Type>);

  const labelRef = useRef<string>(`calendar-body-label-${uniqueId}`);

  const disabled = propDisabled || contextDisabled;
  const required = propRequired || contextRequired;

  const getNativeProps = (suffix = '') => ({
    readOnly: readOnly,
    required,
    disabled,
    'aria-disabled': disabled,
    name: name && `${name}${suffix}`,
    id: controlId,
  });

  return (
    <CalendarContext.Provider
      value={{
        state,
        dispatch,
      }}
    >
      <SharedInputPropsContext.Provider value={{}}>
        <div
          className={clsx(calendarCSS, consumerClassName, {
            [calendarDisabledCSS]: disabled,
          })}
          data-testid={dataTestId}
          ref={calendarRef}
          style={consumerStyle}
          {...remainingProps}
        >
          <CalendarHeader
            view={state.currentView}
            ref={focusAfterViewChangeRef}
            labelId={labelRef.current}
          />
          <div
            data-testid={`${state.currentView}View`}
            aria-labelledby={labelRef.current}
          >
            <table
              role="grid"
              className={calendarBodyCSS({
                isReadOnly: !!readOnly,
              })}
            >
              {renderView(state.currentView)}
            </table>
          </div>
        </div>
      </SharedInputPropsContext.Provider>
      <VisuallyHidden>
        {_isTimeframeV2(state.selectedDate, state.type) ? (
          <>
            <input
              {...eventListeners}
              {...ariaProps}
              {...getNativeProps('-from')}
              ref={ref}
              // Only set if a complete timeframe is available to rely on the browser validation for required.
              value={
                _isCompleteSelection(type, state.selectedDate)
                  ? state.selectedDate?.from?.value
                  : ''
              }
            />
            {/* This input is ONLY used for form submission and not for validation. */}
            <input
              {...getNativeProps('-to')}
              ref={refTo}
              value={state.selectedDate?.to?.value ?? ''}
              id={`${controlId}-to`}
              type="hidden"
            />
          </>
        ) : (
          <input
            {...eventListeners}
            {...ariaProps}
            {...getNativeProps()}
            ref={ref}
            value={state.selectedDate?.value ?? ''}
          />
        )}
      </VisuallyHidden>
    </CalendarContext.Provider>
  );
}
_MappedCalendar['displayName'] = 'Calendar';

/**
 * Calendar Component
 * @internal
 */
export const _Calendar = forwardRef(_MappedCalendar);
